O.spray=function(c1,c2,leaf,stem){return '<path d="M0 0C10 -40 -6 -90 4 -140" fill="none" stroke="'+stem+'" stroke-width="2"/><path d="M4 -40C30 -48 44 -36 50 -22C28 -26 14 -30 4 -40Z" fill="'+leaf+'"/><path d="M0 -80C-28 -92 -42 -80 -48 -66C-28 -66 -12 -70 0 -80Z" fill="'+leaf+'"/><g transform="translate(5 -148)">'+O.flower5(18,c1,c2)+'</g><g transform="translate(-30 -96) scale(.7)">'+O.flower5(18,c1,c2)+'</g><g transform="translate(34 -78) scale(.62)">'+O.flower5(18,c1,c2)+'</g><circle cx="26" cy="-110" r="3.4" fill="'+c1+'"/><circle cx="-14" cy="-122" r="3" fill="'+c1+'"/>';};
